import json,sys
data=json.load(sys.stdin)
doc=data.get('document',{})
elements=doc.get('elements',[])
for i,e in enumerate(elements):
    if e.get('type') == 'table':
        caption = e.get('table',{}).get('caption','')
        if 'Budget' in caption or 'Outlay' in caption or 'interest' in caption.lower():
            print(f'Index {i}: {caption[:200]}')"

